from ..objects.mosaiq_plan_promoting_objects import PlanPromoting
from interops.libraries.squish_actions import CommonActions

def __find_group_edit_treatment_fields_dialog() -> bool:
    """Searches for main Group Edit Treatment Fields Dialog UI. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the edit_treatment_fields.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(PlanPromoting.groupEdit_Treatment_Fields_Dialog) is not None else False

def set_treatment_fields_site_name(siteName: str) -> None:
    """Locates the Group Edit Treatment Fields Dialog UI > clicks the Site Name Combo box > searches for the given siteName option within the combo box drop down >
    then selects the found item (returns None if no item is found).

    :param siteName: String value of the Site Name that will be searched for and selected from the Site Name Combo box
    :type siteName: str
    :raises RuntimeError: Raises if the Group Edit Treatment Fields Dialog UI isn't found.
    """
    if __find_group_edit_treatment_fields_dialog() is False:
        raise RuntimeError("Group Edit Treatment Fields Dialog UI was not open at the time set_treatment_fields_site_name() was called.")
    CommonActions.left_click_object(PlanPromoting.groupEdit_Treatment_Fields_Site_Name_ComboBox)
    site_name_object = CommonActions.get_child_object_by_object_text(
        objectList=CommonActions.get_child_objects(PlanPromoting.groupEdit_Treatment_Fields_Site_Name_ComboBox),
        searchText=siteName
    )
    if site_name_object is None:
        return
    CommonActions.left_click_object(site_name_object)

def set_treatment_fields_tolerance_table(toleranceTable: str) -> None:
    """Locates the Group Edit Treatment Fields Dialog UI > clicks the Tolerance Table Combo box > searches for the given toleranceTable option within the combo box drop down >
    then selects the found item (returns None if no item is found).

    :param toleranceTable: String value of the Site Name that will be searched for and selected from the Site Name Combo box
    :type toleranceTable: str
    :raises RuntimeError: Raises if the Group Edit Treatment Fields Dialog UI isn't found.
    """
    if __find_group_edit_treatment_fields_dialog() is False:
        raise RuntimeError("Group Edit Treatment Fields Dialog UI was not open at the time sset_treatment_fields_tolerance_table() was called.")
    CommonActions.left_click_object(PlanPromoting.groupEdit_Treatment_Fields_Tolerance_Table_ComboBox)
    tolerance_table_object = CommonActions.get_child_object_by_object_text(
        objectList=CommonActions.get_child_objects(PlanPromoting.groupEdit_Treatment_Fields_Tolerance_Table_ComboBox),
        searchText=toleranceTable
    )
    if tolerance_table_object is None:
        return
    CommonActions.left_click_object(tolerance_table_object)

def click_group_edit_treatment_fields_ok_button() -> None:
    """Locates the Group Edit Treatment Fields Dialog UI > clicks the OK button and then waits for the Group Edit Treatment Fields Dialog UI to disappear.

    :raises RuntimeError: Raises if the Group Edit Treatment Fields Dialog UI isn't found.
    """
    if __find_group_edit_treatment_fields_dialog() is False:
        raise RuntimeError("Group Edit Treatment Fields Dialog UI was not open at the time click_group_edit_treatment_fields_ok_button() was called.")
    CommonActions.left_click_object(PlanPromoting.groupEdit_Treatment_Fields_OK_Button)
    CommonActions.wait_for_object_to_disappear(PlanPromoting.groupEdit_Treatment_Fields_Dialog)